import json
import re
import csv

usd_cny = 7.203700065612793
eur_cny = 8.174271583557129
sgd_cny = 5.576481819152832
eur_try = 45.006690979003906
try_cny = eur_cny / eur_try

def to_cny(amount, currency):
    rates = {'USD': usd_cny, 'EUR': eur_cny, 'TRY': try_cny, 'CNY': 1.0, 'SGD': sgd_cny}
    return amount * rates.get(currency.strip(), 0)

people = {
    'Andrew': ('/app/Andrew\'s Istanbul expenses.csv', '/app/memory_Andrew.md', 'mixed'),
    'Lau': ('/app/Lau\'s expensive.csv', '/app/memory_Lau.md', 'columns'),
    'Chen': ('/app/Chen\'s expenses.csv', '/app/memory_Chen.md', 'mixed'),
    'Diana': ('/app/Diana\'s travel log.csv', '/app/memory_Diana.md', 'columns'),
    'Elena': ('/app/Elena\'s trip expenses.csv', '/app/memory_Elena.md', 'amount_currency'),
    'Frank': ('/app/Frank\'s vacation costs.csv', '/app/memory_Frank.md', 'columns'),
    'Grace': ('/app/Grace\'s budget tracker.csv', '/app/memory_Grace.md', 'amount_columns'),
}

results = {}

for person, (csvf, mdf, ctype) in people.items():
    expenses = {'USD': 0, 'EUR': 0, 'TRY': 0, 'CNY': 0, 'SGD': 0}
    with open(csvf) as f:
        reader = csv.DictReader(f)
        if ctype == 'mixed':
            for row in reader:
                cost_str = row['Cost'].strip()
                for cur in ['USD', 'EUR', 'TRY', 'CNY']:
                    if cost_str.endswith(cur):
                        expenses[cur] += float(cost_str[:-len(cur)].strip())
                        break
        elif ctype == 'columns':
            with open(csvf) as f2:
                reader2 = csv.DictReader(f2)
                for row in reader2:
                    for col in ['USD', 'EUR', 'TRY', 'CNY']:
                        val = row.get(col, '').strip()
                        if val:
                            expenses[col] += float(val)
        elif ctype == 'amount_currency':
            with open(csvf) as f2:
                reader2 = csv.DictReader(f2)
                for row in reader2:
                    expenses[row['Currency'].strip()] += float(row['Amount'].strip())
        elif ctype == 'amount_columns':
            with open(csvf) as f2:
                reader2 = csv.DictReader(f2)
                for row in reader2:
                    mapping = [('Amount_CNY','CNY'),('Amount_USD','USD'),('Amount_EUR','EUR'),('Amount_TRY','TRY')]
                    for col, cur in mapping:
                        val = row.get(col, '').strip()
                        if val:
                            expenses[cur] += float(val)
    with open(mdf) as f:
        content = f.read()
    for match in re.finditer(r'(\d+\.?\d*)\s*(USD|EUR|TRY|CNY|SGD)', content):
        expenses[match.group(2)] += float(match.group(1))
    result = sum(to_cny(v, k) for k, v in expenses.items())
    results[person] = round(result, 4)
    print(f"{person}: {expenses} => {round(result, 4)} CNY")

total = sum(results.values())
output = {
    "USD_to_CNY": round(usd_cny, 8),
    "EUR_to_CNY": round(eur_cny, 8),
    "TRY_to_CNY": round(try_cny, 8),
    "SGD_to_CNY": round(sgd_cny, 8),
    "Andrew_Expenses (in CNY)": round(results['Andrew'], 4),
    "Lau_Expenses (in CNY)": round(results['Lau'], 4),
    "Chen_Expenses (in CNY)": round(results['Chen'], 4),
    "Diana_Expenses (in CNY)": round(results['Diana'], 4),
    "Elena_Expenses (in CNY)": round(results['Elena'], 4),
    "Frank_Expenses (in CNY)": round(results['Frank'], 4),
    "Grace_Expenses (in CNY)": round(results['Grace'], 4),
    "Total_Cost (in CNY)": round(total, 4)
}
with open('/app/calculation.json', 'w') as f:
    json.dump(output, f, indent=4)
print("\n=== Final Result ===")
print(json.dumps(output, indent=4))
